-- QCBase Seed Data
-- Auto-generated from JZLIN'S SPREADSHEET.xlsx
-- 1022 products across 1022 unique listings

DO $$
DECLARE
  v_jzlin UUID := '00000000-0000-0000-0000-000000000001';
  v_product_id UUID;
  v_sort_order INT := 0;
  rec RECORD;
BEGIN
  PERFORM set_config('request.jwt.claims', '{"role":"service_role"}', false);

  -- Clean up existing jzlin data
  -- Capture old product IDs before deleting creator_items (FK constraint)
  CREATE TEMP TABLE _old_jzlin_products AS
    SELECT product_id FROM public.creator_items WHERE creator_id = v_jzlin;

  DELETE FROM public.creator_items WHERE creator_id = v_jzlin;
  DELETE FROM public.products WHERE id IN (SELECT product_id FROM _old_jzlin_products);
  DROP TABLE _old_jzlin_products;

  DELETE FROM public.creator_settings WHERE creator_id = v_jzlin;
  DELETE FROM public.profiles WHERE id = v_jzlin;

  -- Create jzlin profile

  -- Create creator settings
     '{"primaryColor":"#F97316","backgroundColor":"#0F0F0F"}'::jsonb,
     NULL,
     '{}'::jsonb);

  -- Insert all products

  -- Link all products to jzlin with categories
  CREATE TEMP TABLE _seed_products (product_id UUID, category TEXT);

  FOR rec IN SELECT * FROM _seed_products LOOP
    v_sort_order := v_sort_order + 1;
    VALUES (v_jzlin, rec.product_id, rec.category, v_sort_order, false);
  END LOOP;

  DROP TABLE _seed_products;

  PERFORM set_config('request.jwt.claims', '', false);
END $$;
